# Test hypothesis: Change unreachable zeros that can reach LEFT edge OR BOTTOM edge
def apply_rule(grid):
    new_grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    changed = set()

    def can_reach_topleft(pos):
        vis = {pos}
        q = [pos]
        while q:
            r,c = q.pop(0)
            if r==0 and c==0:
                return True
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols:
                    if grid[nr][nc]==0 and (nr,nc) not in vis:
                        vis.add((nr,nc))
                        q.append((nr,nc))
        return False

    def can_reach_left(pos):
        vis = {pos}
        q = [pos]
        while q:
            r,c = q.pop(0)
            if c == 0:
                return True
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols:
                    if grid[nr][nc]==0 and (nr,nc) not in vis:
                        vis.add((nr,nc))
                        q.append((nr,nc))
        return False

    def can_reach_bottom(pos):
        vis = {pos}
        q = [pos]
        while q:
            r,c = q.pop(0)
            if r == rows-1:
                return True
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols:
                    if grid[nr][nc]==0 and (nr,nc) not in vis:
                        vis.add((nr,nc))
                        q.append((nr,nc))
        return False

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                if not can_reach_topleft((r,c)):
                    reaches_left = can_reach_left((r,c))
                    reaches_bottom = can_reach_bottom((r,c))
                    if reaches_left or reaches_bottom:
                        changed.add((r,c))

    for r,c in changed:
        new_grid[r][c] = 5

    return new_grid, changed

