    comp = []
    queue = [(r,c)]
    comp_visited = {(r,c)}

    while queue:
        cr,cc = queue.pop(0)
        comp.append((cr,cc))
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc = cr+dr, cc+dc
            if (nr,nc) in all_unreachable and (nr,nc) not in comp_visited:
                comp_visited.add((nr,nc))
                queue.append((nr,nc))

    visited.update(comp)
    components_list.append(comp)

print(f"Found {len(components_list)} components of unreachable zeros")

for i, comp in enumerate(sorted(components_list, key=lambda c: len(c), reverse=True)[:10]):
    print(f"Comp {i}: size={len(comp)}")

# Now apply rule: change exactly 8 per component (or all if < 8)
changes_made = 0
for comp in sorted(components_list, key=lambda c: len(c)):
    num_to_change = min(8, len(comp))
    # Change by position order (row-major then col-major)
    for j, cell in enumerate(sorted(comp)):
        if j < num_to_change:
            r,c = cell
            result_grid[r][c] = 5
            changes_made += 1

print(f"\nTotal changes made: {changes_made}")

import json
output_json = {"grid": result_grid, "changes_count": changes_made}
with open('/tmp/test_result3.json', 'w') as f:
    json.dump(output_json, f, indent=2)
print("Saved to /tmp/test_result3.json")

# Check dimensions of test_grid
print(f"test_grid shape: {len(test_grid)} x {len(test_grid[0]) if test_grid else 0}")
if len(test_grid) >= 3 and len(test_grid[0]) >= 5:
    print("First 3 rows:")
    for i in range(3):
        print(test_grid[i][:10])

# Generate final submission action
action_json = {"action": "submit", "grid": result_grid}
print(action_json)

import json
# Final submission
result_grid = [row[:] for row in test_grid]
for r in range(len(result_grid)):
    for c in range(len(result_grid[0])):
        if result_grid[r][c] == 0 and not can_reach_topleft((r,c)) and c < 13:
            result_grid[r][c] = 5

print('{"action": "submit", "grid": ' + json.dumps(result_grid) + '}')
